INSERT INTO `recettes` (`id`, `type_cuisine`, `nom_recette`, `ingredients`, `etapes`, `image_url`, `commentaire`) VALUES
(1, 'salée', 'poulet yassa', '1 poulet entier (environ 1.5 kg) coupé en morceaux (ou des cuisses et hauts de cuisses)\r\n 2 gros oignons blancs\r\n  Le jus de 2 à 3 citrons (selon leur taille et votre goût)\r\n  2-3 cuillères à soupe de moutarde (de préférence de Dijon)\r\n					 2-3 gousses d\'ail hachées\r\n					 1-2 piments frais (facultatif, selon votre goût pour le piquant), épépinés et hachés finement\r\n					 1 morceau de gingembre frais (environ 2-3 cm) râpé ou finement haché \r\n					 Huile végétale (arachide, tournesol ou autre) \r\n					  Sel et poivre noir fraîchement moulu \r\n					 Quelques brins de persil frais pour la garniture (facultatif) \r\n					 Olives vertes dénoyautées (facultatif)', '1-Mariner le poulet : Dans un grand saladier, mélangez les morceaux de poulet avec la moitié du jus de citron, la moitié de la moutarde, la moitié de l\'ail haché, la moitié du gingembre râpé, le sel et le poivre. Mélangez bien pour que tous les morceaux soient enrobés. Laissez mariner au réfrigérateur pendant au moins 2 heures, idéalement toute une nuit pour plus de saveur.\r\n\r\n2- Préparer les oignons : Épluchez et émincez finement les oignons.\r\n \r\n3-Mariner les oignons : Dans un autre saladier, mélangez les oignons émincés avec le reste du jus de citron, le reste de la moutarde, le reste de l\'ail haché, le reste du gingembre râpé et les piments hachés (si vous en utilisez). Salez et poivrez légèrement. Laissez mariner pendant au moins 30 minutes..\r\n					 4-À la poêle : Faites chauffer un peu d\'huile végétale dans une grande poêle ou une cocotte à fond épais. Retirez les morceaux de poulet de la marinade (conservez la marinade !) et faites-les dorer sur toutes les faces à feu moyen-vif. Réservez le poulet.\r\n					5-Au four : Préchauffez le four à 180°C (thermostat 6). Disposez les morceaux de poulet marinés sur une plaque de cuisson recouverte de papier sulfurisé et enfournez pour environ 20-25 minutes, jusqu\'à ce qu\'ils soient légèrement dorés..\r\n					 6-Cuisson des oignons et finition :\r\n					Dans la même poêle (si vous avez doré le poulet à la poêle), ajoutez les oignons marinés (avec leur marinade). Faites cuire à feu moyen en remuant de temps en temps jusqu\'à ce qu\'ils deviennent tendres et translucides (environ 15-20 minutes). \r\n					 Ajoutez les morceaux de poulet doré à la poêle avec les oignons. Versez le reste de la marinade du poulet (si vous en avez). \r\n					Baissez le feu, couvrez et laissez mijoter pendant encore 15-20 minutes, ou jusqu\'à ce que le poulet soit bien cuit et la sauce ait légèrement épaissi. Si vous utilisez des olives, ajoutez-les pendant les 5 dernières minutes de cuisson. \r\n					  Baissez le feu, couvrez et laissez mijoter pendant encore 15-20 minutes, ou jusqu\'à ce que le poulet soit bien cuit et la sauce ait légèrement épaissi. Si vous utilisez des olives, ajoutez-les pendant les 5 dernières minutes de cuisson.\r\n					  Si vous avez pré-cuit le poulet au four, ajoutez les oignons marinés dans une grande cocotte et faites-les cuire jusqu\'à ce qu\'ils soient tendres. Ajoutez ensuite le poulet pré-cuit et la marinade du poulet. Laissez mijoter à couvert pendant 15-20 minutes.', 'poulet_yassa.jpeg', ''),
(2, 'salee', 'couscous', '* 300 g de semoule de couscous moyenne\r\n * 4 cuisses de poulet (ou 2 blancs coupés en morceaux)\r\n * 2 oignons moyens, hachés\r\n * 2 carottes, pelées et coupées en rondelles\r\n * 2 courgettes, coupées en dés\r\n * 1 boîte de 400 g de tomates concassées\r\n * 1 cuillère à café de cumin en poudre\r\n * 1 cuillère à café de curcuma en poudre\r\n * 1/2 cuillère à café de gingembre en poudre\r\n * 1/4 cuillère à café de piment de Cayenne (facultatif)\r\n * 400 ml de bouillon de volaille (ou eau)\r\n * 3 cuillères à soupe d\'huile d\'olive\r\n * Sel et poivre noir fraîchement moulu, au goût\r\n * Une poignée de coriandre fraîche, hachée (pour la garniture)\r\n * Quelques raisins secs (facultatif)\r\n * Quelques pois chiches en conserve, rincés et égouttés (facultatif)', '1-Préparation du poulet et des légumes :\r\n * Dans une grande cocotte ou un faitout, faites chauffer l\'huile d\'olive à feu moyen.\r\n * Faites dorer les morceaux de poulet sur toutes les faces jusqu\'à ce qu\'ils soient bien colorés. Retirez-les de la cocotte et réservez-les.\r\n * Dans la même cocotte, ajoutez les oignons hachés et faites-les revenir à feu moyen jusqu\'à ce qu\'ils deviennent translucides (environ 5 minutes).\r\n * Ajoutez les carottes et les courgettes coupées. Faites-les sauter pendant environ 5 minutes en remuant de temps en temps.\r\n * Incorporez les épices : cumin, curcuma, gingembre et piment de Cayenne (si vous en utilisez). Mélangez bien pour enrober les légumes.\r\n * Ajoutez les tomates concassées et le bouillon de volaille (ou l\'eau). Salez et poivrez au goût.\r\n * Remettez les morceaux de poulet dans la cocotte. Portez à ébullition, puis réduisez le feu à doux, couvrez et laissez mijoter pendant environ 25 à 30 minutes, ou jusqu\'à ce que le poulet soit bien cuit et tendre.\r\n * Si vous utilisez des raisins secs et des pois chiches, ajoutez-les dans la cocotte pendant les 10 dernières minutes de cuisson.\r\n2-Préparation de la semoule de couscous :\r\n * Pendant que le poulet mijote, préparez la semoule de couscous. Dans un grand saladier, versez la semoule.\r\n * Ajoutez une pincée de sel et mélangez.\r\n * Versez 400 ml d\'eau bouillante sur la semoule. Couvrez immédiatement le saladier avec un couvercle ou une assiette et laissez reposer pendant 5 à 7 minutes. La vapeur va hydrater la semoule.\r\n * Après le temps de repos, retirez le couvercle et égrenez la semoule à l\'aide d\'une fourchette pour séparer les grains et éviter qu\'ils ne collent. Vous pouvez ajouter une petite noix de beurre ou un filet d\'huile d\'olive à ce moment pour plus de saveur et pour aider à l\'égrenage.\r\nService :\r\n * Disposez la semoule de couscous dans un grand plat de service.\r\n * Nappez la semoule avec la sauce aux légumes et disposez les morceaux de poulet par-dessus.', 'couscous.jpeg', ''),
(3, 'salee', ' Pâtes au Poulet', ' * 250-300 g de pâtes (penne, fusilli, farfalle, etc.)\r\n * 2 filets de poulet, coupés en dés\r\n * 1 oignon moyen, haché\r\n * 2 gousses d\'ail, émincées\r\n * 1 poivron (rouge, jaune ou orange), coupé en lanières\r\n * 1 courgette, coupée en dés\r\n * 400 g de tomates concassées en conserve\r\n * 100 ml de crème liquide (facultatif, pour une sauce plus onctueuse)\r\n * Huile d\'olive\r\n * Origan séché\r\n * Basilic séché\r\n * Sel et poivre noir fraîchement moulu, au goût\r\n * Parmesan râpé (pour servir)\r\n * Persil frais, haché (pour la garniture)', ' * Cuire les pâtes : Faites cuire les pâtes selon les instructions sur l\'emballage dans une grande casserole d\'eau bouillante salée. Égouttez-les en conservant une tasse d\'eau de cuisson. Réservez.\r\n * Cuire le poulet : Pendant que les pâtes cuisent, faites chauffer un filet d\'huile d\'olive dans une grande poêle à feu moyen-vif. Ajoutez les dés de poulet et faites-les dorer sur toutes les faces jusqu\'à ce qu\'ils soient bien cuits à l\'intérieur (environ 5-7 minutes). Assaisonnez avec du sel et du poivre. Retirez le poulet de la poêle et réservez-le.\r\n * Faire revenir les légumes : Dans la même poêle, ajoutez un peu d\'huile d\'olive si nécessaire. Faites revenir l\'oignon haché jusqu\'à ce qu\'il devienne translucide (environ 3-4 minutes). Ajoutez ensuite l\'ail émincé et faites cuire pendant une minute de plus, jusqu\'à ce qu\'il soit parfumé (attention à ne pas le brûler).\r\n * Ajouter les poivrons et la courgette : Incorporez les lanières de poivron et les dés de courgette dans la poêle. Faites cuire pendant environ 5-7 minutes, jusqu\'à ce qu\'ils soient tendres mais encore légèrement croquants.\r\n * Préparer la sauce tomate : Ajoutez les tomates concassées dans la poêle. Assaisonnez avec l\'origan, le basilic, le sel et le poivre. Laissez mijoter la sauce à feu doux pendant environ 5 minutes, en remuant de temps en temps.\r\n * Assembler le plat : Ajoutez le poulet cuit dans la sauce tomate et mélangez pour l\'enrober. Si vous le souhaitez, incorporez la crème liquide pour une sauce plus riche et onctueuse. Laissez chauffer doucement pendant une minute.\r\n * Mélanger les pâtes à la sauce : Ajoutez les pâtes égouttées dans la poêle avec la sauce au poulet et aux légumes. Mélangez bien pour que les pâtes soient complètement enrobées de sauce. Si la sauce est trop épaisse, ajoutez un peu d\'eau de cuisson des pâtes pour l\'alléger.\r\n * Servir : Servez les pâtes au poulet chaudes, garnies de parmesan râpé et de persil frais haché.\r\nVariations possibles :\r\n * Ajouter d\'autres légumes : Des champignons, des épinards, des brocolis ou des petits pois peuvent être ajoutés à la recette.\r\n * Utiliser différentes herbes : Du thym, du romarin ou de la sauge peuvent remplacer ou compléter l\'origan et le basilic.\r\n * Sauce crémeuse différente : Vous pouvez utiliser du fromage frais, de la ricotta ou du mascarpone à la place de la crème liquide.\r\n * Ajouter du vin blanc : Après avoir fait revenir les oignons et l\'ail, vous pouvez déglacer la poêle avec un peu de vin blanc sec avant d\'ajouter les tomates. Laissez réduire quelques minutes.\r\n * Version épicée : Ajoutez une pincée de piment rouge ou quelques gouttes de sauce piquante à la sauce tomate.', 'pates au poulet.jpeg', ''),
(4, 'salee', 'Riz sauté au poulet', ' * 2 tasses de riz cuit froid (idéalement de la veille, car il est moins collant)\r\n * 2 blancs de poulet, coupés en petits dés\r\n * 1 oignon moyen, haché\r\n * 2 gousses d\'ail, émincées\r\n * 1 carotte, coupée en petits dés\r\n * 1 poivron (rouge, jaune ou vert), coupé en petits dés\r\n * 1 tasse de petits pois (frais ou surgelés)\r\n * 2 œufs\r\n * 2-3 cuillères à soupe de sauce soja\r\n * 1 cuillère à soupe de sauce huître (facultatif)\r\n * 1 cuillère à café d\'huile de sésame\r\n * Huile végétale (pour la cuisson)\r\n * Sel et poivre noir fraîchement moulu, au goût\r\n * Ciboulette ou oignon vert haché (pour la garniture)\r\n * Graines de sésame (pour la garniture, facultatif)', '* Préparer les ingrédients : Assurez-vous que tous vos légumes sont coupés en petits morceaux de taille similaire. Si vous utilisez des petits pois surgelés, décongelez-les rapidement sous l\'eau tiède.\r\n * Cuire le poulet : Faites chauffer une grande poêle ou un wok à feu moyen-vif avec un peu d\'huile végétale. Ajoutez les dés de poulet et faites-les sauter jusqu\'à ce qu\'ils soient bien cuits et dorés. Retirez le poulet de la poêle et mettez-le de côté.\r\n * Cuire les légumes : Ajoutez un peu plus d\'huile dans la poêle si nécessaire. Faites sauter l\'oignon haché pendant environ 2 minutes, jusqu\'à ce qu\'il devienne translucide. Ajoutez ensuite l\'ail émincé, la carotte et le poivron. Faites sauter pendant 3-5 minutes, jusqu\'à ce que les légumes soient tendres mais encore légèrement croquants. Ajoutez les petits pois et faites cuire encore 1 minute.\r\n * Cuire les œufs : Poussez les légumes sur un côté de la poêle et cassez les œufs sur l\'espace vide. Brouillez-les rapidement avec une spatule jusqu\'à ce qu\'ils soient cuits. Mélangez ensuite les œufs brouillés avec les légumes.\r\n * Ajouter le riz : Ajoutez le riz cuit froid dans la poêle et émiettez-le avec votre spatule pour séparer les grains. Mélangez bien avec les légumes et les œufs.\r\n * Assaisonner : Versez la sauce soja et la sauce huître (si vous l\'utilisez) sur le riz. Ajoutez l\'huile de sésame. Salez et poivrez au goût. Mélangez bien pour que tous les ingrédients soient enrobés de sauce et que le riz soit bien chaud.\r\n * Incorporer le poulet : Remettez le poulet cuit dans la poêle et mélangez-le avec le riz et les légumes. Faites chauffer le tout pendant encore une minute.\r\n * Servir : Servez le riz sauté au poulet chaud, garni de ciboulette ou d\'oignon vert haché et de graines de sésame (si désiré).', 'riz.jpeg', ''),
(5, 'salee', 'salade', '* 1 laitue (ou un mélange de salades)\r\n * 2 tomates\r\n * 1 concombre\r\n * 1 poivron (de la couleur de ton choix)\r\n * 1 oignon rouge (facultatif)\r\n * Des olives (noires ou vertes)\r\n * De la feta (ou de la mozzarella)\r\n * Des herbes fraîches ciselées (persil, ciboulette, basilic...)\r\n * Pour la vinaigrette :\r\n   * 3 cuillères à soupe d\'huile d\'olive\r\n   * 1 cuillère à soupe de vinaigre (de vin, balsamique, ou de cidre)\r\n   * 1/2 cuillère à café de moutarde (facultatif)\r\n   * Sel et poivre au goût', ' * Lave et essore soigneusement la laitue. Déchire les feuilles en morceaux et place-les dans un grand saladier.\r\n * Lave et coupe les tomates en quartiers ou en rondelles.\r\n * Lave et coupe le concombre en rondelles ou en dés.\r\n * Lave, épépine et coupe le poivron en fines lanières.\r\n * Si tu utilises de l\'oignon rouge, pèle-le et émince-le finement.\r\n * Ajoute les tomates, le concombre, le poivron et l\'oignon rouge (si utilisé) à la salade.\r\n * Incorpore les olives et le fromage coupé en dés ou émietté.\r\n * Cisèle les herbes fraîches et parsème-les sur la salade.\r\n * Prépare la vinaigrette dans un petit bol en mélangeant l\'huile d\'olive, le vinaigre, la moutarde (si utilisée), le sel et le poivre. Tu peux émulsionner la vinaigrette en la fouettant ou en la secouant dans un petit bocal fermé.\r\n * Verse la vinaigrette sur la salade juste avant de servir et mélange délicatement pour bien enrober tous les ingrédients.', 'salade.jpeg', ''),
(6, 'sucree', 'gateau au chocolat', '* 200g de chocolat noir (minimum 50% de cacao)\r\n * 150g de beurre demi-sel (ou doux avec une pincée de sel)\r\n * 150g de sucre en poudre\r\n * 3 œufs\r\n * 80g de farine\r\n * 1/2 sachet de levure chimique (environ 5g)\r\n * (Facultatif) 1 cuillère à café d\'extrait de vanille', ' * Préchauffe ton four à 180°C (thermostat 6). Beurres et farines un moule rond d\'environ 20-22 cm de diamètre (ou utilise du papier sulfurisé).\r\n * Fais fondre le chocolat et le beurre ensemble à feu doux dans une casserole ou au bain-marie. Mélange jusqu\'à obtenir une pâte lisse et homogène. Retire du feu.\r\n * Ajoute le sucre au mélange chocolat-beurre et mélange bien.\r\n * Incorpore les œufs un par un en mélangeant bien après chaque ajout.\r\n * Ajoute l\'extrait de vanille si tu en utilises.\r\n * Dans un autre bol, mélange la farine et la levure chimique.\r\n * Incorpore progressivement le mélange farine-levure à la préparation chocolatée en mélangeant délicatement jusqu\'à obtenir une pâte lisse et sans grumeaux.\r\n * Verse la pâte dans le moule préparé et répartis-la uniformément.\r\n * Enfourne pour 20 à 25 minutes. Le temps de cuisson peut varier légèrement en fonction de ton four. Le gâteau est prêt lorsque le centre est encore légèrement moelleux et qu\'une croûte s\'est formée sur le dessus. Pour vérifier la cuisson, tu peux insérer la pointe d\'un couteau au centre : elle doit ressortir avec quelques miettes humides.\r\n * Laisse tiédir le gâteau dans le moule avant de le démouler sur une grille et de le laisser refroidir complètement.', 'gateau.jpeg', ''),
(7, 'sucree', 'cookies', '* 125g de beurre mou (à température ambiante)\r\n * 100g de sucre en poudre\r\n * 75g de cassonade (sucre roux)\r\n * 1 œuf\r\n * 1 cuillère à café d\'extrait de vanille\r\n * 225g de farine\r\n * 1/2 cuillère à café de bicarbonate de soude\r\n * 1/4 cuillère à café de sel\r\n * 150g de pépites de chocolat (lait, noir, ou un mélange)', '* Préchauffe ton four à 180°C (thermostat 6). Recouvre une ou deux plaques de cuisson de papier sulfurisé.\r\n * Dans un grand saladier, crémé le beurre mou avec le sucre en poudre et la cassonade à l\'aide d\'une spatule, d\'une fourchette ou d\'un batteur électrique jusqu\'à obtenir un mélange léger et mousseux.\r\n * Incorpore l\'œuf et l\'extrait de vanille et mélange bien.\r\n * Dans un autre bol, mélange la farine, le bicarbonate de soude et le sel.\r\n * Ajoute progressivement le mélange sec (farine, bicarbonate, sel) au mélange humide (beurre, sucre, œuf) en mélangeant juste assez pour combiner les ingrédients. Ne mélange pas trop, sinon les cookies risquent d\'être durs.\r\n * Incorpore délicatement les pépites de chocolat à la pâte.\r\n * À l\'aide d\'une cuillère à glace ou de deux cuillères, dépose des boules de pâte sur les plaques de cuisson préparées, en les espaçant d\'environ 5 cm car ils vont s\'étaler à la cuisson.\r\n * Enfourne pour 10 à 12 minutes, jusqu\'à ce que les bords des cookies soient dorés et le centre encore légèrement mou. Attention, ils durcissent en refroidissant.\r\n * Laisse les cookies refroidir quelques minutes sur la plaque avant de les transférer délicatement sur une grille pour qu\'ils refroidissent complètement.', 'cookies.jpeg', ''),
(8, 'sucree', 'pancakes', ' * 200g de farine\r\n * 1 cuillère à soupe de sucre\r\n * 1 sachet de levure chimique (environ 1 cuillère à café)\r\n * 1 pincée de sel\r\n * 2 œufs\r\n * 250ml de lait\r\n * 30g de beurre fondu (plus un peu pour la cuisson)\r\n * (Facultatif) Quelques gouttes d\'extrait de vanille', ' * Dans un grand saladier, mélange la farine, le sucre, la levure chimique et le sel.\r\n * Dans un autre bol, bats légèrement les œufs avec le lait et le beurre fondu. Ajoute l\'extrait de vanille si tu en utilises.\r\n * Verse le mélange liquide sur le mélange sec et mélange juste assez pour combiner les ingrédients. Il est normal qu\'il reste quelques grumeaux, ne mélange pas trop, sinon les pancakes seront moins moelleux.\r\n * Fais chauffer une poêle légèrement huilée ou beurrée à feu moyen.\r\n * Verse une louche de pâte dans la poêle chaude. Laisse cuire environ 1 à 2 minutes sur la première face, jusqu\'à ce que de petites bulles apparaissent à la surface et que les bords commencent à dorer.\r\n * Retourne délicatement le pancake à l\'aide d\'une spatule et fais cuire l\'autre face pendant environ 1 minute, jusqu\'à ce qu\'elle soit également dorée.\r\n * Répète l\'opération avec le reste de la pâte, en ajoutant un peu de beurre dans la poêle si nécessaire.\r\n * Empile les pancakes au fur et à mesure sur une assiette.\r\nSuggestions de dégustation :\r\n * Sirop d\'érable\r\n * Fruits frais (fraises, framboises, myrtilles, bananes...)\r\n * Crème fouettée\r\n * Nutella ou pâte à tartiner\r\n * Confiture\r\n * Miel\r\n * Beurre fondu et sucre glace', 'pancakes.jpeg', ''),
(9, 'sucree', 'tarte au pommes', ' * Pour la pâte brisée :\r\n   * 250g de farine\r\n   * 125g de beurre froid coupé en dés\r\n   * 1 pincée de sel\r\n   * Environ 50ml d\'eau froide\r\n * Pour la garniture :\r\n   * Environ 1 kg de pommes (variétés comme la Golden, la Reinette, la Gala, ou un mélange)\r\n   * 50 à 80g de sucre (selon l\'acidité des pommes et ton goût)\r\n   * 1 cuillère à café de cannelle en poudre (facultatif)\r\n   * Le jus d\'un demi-citron (pour éviter l\'oxydation des pommes)\r\n   * 20g de beurre (en petites noisettes)\r\n   * (Facultatif) 1 jaune d\'œuf battu avec un peu de lait pour dorer la pâte', ' * Prépare la pâte brisée :\r\n   * Dans un grand saladier, mélange la farine et le sel.\r\n   * Ajoute le beurre froid en dés et travaille du bout des doigts jusqu\'à obtenir une texture sableuse (comme de la chapelure grossière).\r\n   * Ajoute l\'eau froide petit à petit, en mélangeant à la fourchette, jusqu\'à ce que la pâte commence à se former en boule. Ne travaille pas trop la pâte.\r\n   * Forme une boule, enveloppe-la dans du film alimentaire et place-la au réfrigérateur pendant au moins 30 minutes.\r\n * Prépare la garniture :\r\n   * Pèle, épépine et coupe les pommes en tranches d\'environ 5 mm d\'épaisseur.\r\n   * Dans un grand bol, mélange les tranches de pommes avec le sucre, la cannelle (si utilisée) et le jus de citron.\r\n * Préchauffe ton four à 180°C (thermostat 6).\r\n * Étale la pâte brisée :\r\n   * Sur un plan de travail légèrement fariné, étale la moitié de la pâte en un cercle d\'environ 30 cm de diamètre (pour un moule de 24-26 cm).\r\n   * Dépose délicatement la pâte dans ton moule à tarte. Pince les bords pour former une jolie bordure.\r\n   * (Facultatif) Pique le fond de la pâte avec une fourchette pour éviter qu\'elle ne gonfle à la cuisson.\r\n * Garnis la tarte :\r\n   * Dispose les tranches de pommes en rosace ou en cercles concentriques sur le fond de tarte. Essaie de les serrer un peu car elles vont réduire à la cuisson.\r\n   * Répartis les petites noisettes de beurre sur les pommes.\r\n * (Facultatif) Prépare le dessus de la tarte :\r\n   * Tu peux simplement laisser la tarte telle quelle.\r\n   * Ou bien, tu peux étaler le reste de la pâte et la découper en lanières pour former un quadrillage sur le dessus de la tarte. Colle les extrémités des lanières à la bordure de la pâte du dessous.\r\n   * Ou encore, tu peux découper des formes dans le reste de la pâte (feuilles, étoiles...) pour décorer le dessus.\r\n * Dore la pâte (facultatif) :\r\n   * Si tu le souhaites, badigeonne la bordure (et le dessus si tu as fait une décoration) avec le jaune d\'œuf battu avec un peu de lait pour une belle couleur dorée.\r\n * Enfourne pour 35 à 45 minutes, ou jusqu\'à ce que la pâte soit bien dorée et que les pommes soient tendres. Le temps de cuisson peut varier en fonction de ton four et de l\'épaisseur des pommes.\r\n * Laisse tiédir la tarte avant de la déguster. Elle est délicieuse tiède ou froide !', 'tarte.jpeg', ''),
(10, 'sucree', 'biscuits au coco', '* 100g de beurre mou (à température ambiante)\r\n * 80g de sucre en poudre\r\n * 1 œuf\r\n * 1 cuillère à café d\'extrait de vanille\r\n * 150g de noix de coco râpée\r\n * 50g de farine\r\n * 1/2 cuillère à café de levure chimique\r\n * Une pincée de sel', '* Préchauffe ton four à 180°C (thermostat 6). Recouvre une plaque de cuisson de papier sulfurisé.\r\n * Dans un saladier, créme le beurre mou avec le sucre en poudre jusqu\'à obtenir un mélange léger et mousseux.\r\n * Incorpore l\'œuf et l\'extrait de vanille et mélange bien.\r\n * Ajoute la noix de coco râpée et mélange pour bien l\'incorporer à la pâte.\r\n * Dans un autre bol, mélange la farine, la levure chimique et le sel.\r\n * Ajoute progressivement le mélange sec au mélange humide en mélangeant juste assez pour combiner les ingrédients.\r\n * À l\'aide de deux cuillères ou d\'une petite cuillère à glace, dépose des petits tas de pâte sur la plaque de cuisson préparée, en les espaçant légèrement. Ils ne s\'étaleront pas beaucoup.\r\n * Enfourne pour 10 à 12 minutes, jusqu\'à ce que les bords des biscuits soient légèrement dorés. Le centre restera un peu moelleux.\r\n * Laisse les biscuits refroidir quelques minutes sur la plaque avant de les transférer délicatement sur une grille pour qu\'ils refroidissent complètement.', 'biscuit.jpeg', ''),
(11, 'vegetarienne', 'ragout de patate douce', '* 2 grosses patates douces (environ 800g), pelées et coupées en cubes de 2-3 cm\r\n * 1 gros oignon, haché\r\n * 2 gousses d\'ail, émincées\r\n * 1 poivron (couleur au choix), épépiné et coupé en dés\r\n * 1 boîte de 400g de tomates concassées\r\n * 400ml de bouillon de légumes\r\n * 1 boîte de 400g de pois chiches, rincés et égouttés\r\n * 1 cuillère à café de cumin en poudre\r\n * 1/2 cuillère à café de curcuma en poudre\r\n * 1/2 cuillère à café de paprika (doux ou fumé)\r\n * 1 feuille de laurier\r\n * Huile d\'olive\r\n * Sel et poivre au goût\r\n * Coriandre fraîche ciselée (pour la garniture)\r\n(Facultatif) Pour plus de saveur et de consistance :\r\n * 1 carotte, pelée et coupée en rondelles\r\n * 1 branche de céleri, coupée en dés\r\n * Une poignée d\'épinards frais\r\n * Un peu de lait de coco pour une touche crémeuse', ' * Dans une grande cocotte ou une marmite, fais chauffer un peu d\'huile d\'olive à feu moyen.\r\n * Ajoute l\'oignon haché et fais-le revenir pendant 5 minutes, jusqu\'à ce qu\'il soit translucide.\r\n * Ajoute l\'ail émincé et fais cuire pendant 1 minute de plus, en faisant attention à ce qu\'il ne brûle pas.\r\n * Ajoute le poivron en dés (et la carotte et le céleri si tu les utilises) et fais cuire pendant 5 minutes, en remuant de temps en temps.\r\n * Ajoute les épices (cumin, curcuma, paprika) et mélange bien pour enrober les légumes. Laisse cuire 1 minute pour libérer les arômes.\r\n * Ajoute les cubes de patates douces, les tomates concassées, le bouillon de légumes et la feuille de laurier.\r\n * Porte à ébullition, puis réduis le feu, couvre et laisse mijoter pendant 20 à 25 minutes, ou jusqu\'à ce que les patates douces soient tendres mais encore légèrement fermes.\r\n * Ajoute les pois chiches rincés et égouttés (et les épinards si tu les utilises). Laisse mijoter encore 5 minutes pour réchauffer les pois chiches et faire tomber les épinards.\r\n * Si tu souhaites une texture plus crémeuse, tu peux ajouter un peu de lait de coco à la fin et laisser mijoter doucement pendant quelques minutes.\r\n * Retire la feuille de laurier.\r\n * Assaisonne de sel et de poivre selon ton goût.\r\n * Sers le ragoût chaud, garni de coriandre fraîche ciselée.', 'ragout.jpeg', ''),
(12, 'vegetarienne', 'salade de pomme de terre', ' * 1 kg de pommes de terre (type charlotte, amandine, ou autres pommes de terre fermes)\r\n * 2 œufs durs\r\n * 1 oignon rouge (petit), finement haché (facultatif)\r\n * Quelques brins de ciboulette fraîche, ciselée\r\n * Quelques brins de persil frais, ciselé\r\n * Pour la sauce crémeuse :\r\n   * 150g de mayonnaise\r\n   * 2 cuillères à soupe de moutarde (de Dijon, à l\'ancienne...)\r\n   * 2 cuillères à soupe de vinaigre de cidre (ou blanc)\r\n   * 1 cuillère à soupe d\'huile d\'olive (facultatif)\r\n   * Sel et poivre au goût\r\n(Facultatif) Autres ingrédients possibles :\r\n * Cornichons aigres-doux, coupés en petits dés\r\n * Câpres, égouttées\r\n * Lardons fumés, revenus à la poêle et égouttés\r\n * Thon au naturel, émietté\r\n * Olives noires ou vertes, coupées en rondelles\r\n * Céleri branche, coupé en petits dés', '* Faites cuire les pommes de terre : Lavez bien les pommes de terre et mettez-les dans une grande casserole d\'eau salée. Portez à ébullition et laissez cuire jusqu\'à ce qu\'elles soient tendres mais encore fermes (environ 20-25 minutes selon la taille). Vous devez pouvoir les piquer facilement avec la pointe d\'un couteau.\r\n * Faites cuire les œufs durs : Pendant la cuisson des pommes de terre, faites cuire les œufs durs dans une autre casserole (environ 9-10 minutes à partir de l\'ébullition). Écalez-les et coupez-les en quartiers ou en dés.\r\n * Préparez la sauce : Dans un saladier, mélangez la mayonnaise, la moutarde, le vinaigre (et l\'huile d\'olive si vous l\'utilisez). Salez et poivrez au goût.\r\n * Coupez les pommes de terre : Égouttez les pommes de terre et laissez-les tiédir légèrement. Coupez-les en morceaux de la taille souhaitée (rondelles, dés...). Si la peau est fine, vous pouvez la laisser.\r\n * Assemblez la salade : Dans le saladier contenant la sauce, ajoutez les morceaux de pommes de terre tièdes, les œufs durs coupés, l\'oignon rouge haché (si vous l\'utilisez), la ciboulette et le persil ciselés.\r\n * Mélangez délicatement pour bien enrober tous les ingrédients de sauce.\r\n * Rectifiez l\'assaisonnement si nécessaire.\r\n * Laissez refroidir la salade au réfrigérateur pendant au moins 30 minutes pour que les saveurs se mélangent bien.', 'salade pomme.jpeg', ''),
(13, 'vegetarienne', 'couscous vegetarien', ' * 250g de couscous moyen\r\n * 2 cuillères à soupe d\'huile d\'olive\r\n * 1 gros oignon, haché\r\n * 2 gousses d\'ail, émincées\r\n * 1 poivron (couleur au choix), épépiné et coupé en morceaux\r\n * 2 carottes, pelées et coupées en rondelles\r\n * 2 courgettes, coupées en gros morceaux\r\n * 1 boîte de 400g de tomates concassées\r\n * 400ml de bouillon de légumes\r\n * 1 boîte de 400g de pois chiches, rincés et égouttés\r\n * 100g de raisins secs\r\n * 50g d\'amandes effilées (facultatif)\r\n * 1 cuillère à café de cumin en poudre\r\n * 1/2 cuillère à café de curcuma en poudre\r\n * 1/2 cuillère à café de gingembre en poudre\r\n * 1/4 cuillère à café de cannelle en poudre\r\n * Quelques brins de coriandre fraîche, ciselée\r\n * Sel et poivre au goût\r\n(Facultatif) Pour plus de saveur et de légumes :\r\n * 1 navet, pelé et coupé en cubes\r\n * 1 morceau de potimarron ou de butternut, pelé et coupé en cubes\r\n * Quelques fleurs de chou-fleur ou de brocoli\r\n * Une poignée d\'épinards frais ou surgelés', ' * Préparez les légumes : Lavez, pelez et coupez tous les légumes selon les instructions.\r\n * Faites revenir les aromates : Dans un grand faitout ou une cocotte, faites chauffer l\'huile d\'olive à feu moyen. Ajoutez l\'oignon haché et faites-le revenir jusqu\'à ce qu\'il soit translucide (environ 5 minutes). Ajoutez l\'ail émincé et faites cuire pendant 1 minute de plus sans le laisser brûler.\r\n * Ajoutez les épices : Incorporez le cumin, le curcuma, le gingembre et la cannelle. Faites cuire pendant 1 minute en remuant pour libérer leurs arômes.\r\n * Ajoutez les légumes : Ajoutez le poivron, les carottes (et le navet et le potimarron si vous les utilisez). Faites revenir pendant 5 minutes en remuant de temps en temps.\r\n * Incorporez les tomates et le bouillon : Versez les tomates concassées et le bouillon de légumes. Salez et poivrez. Portez à ébullition, puis réduisez le feu, couvrez et laissez mijoter pendant 15 minutes.\r\n * Ajoutez les légumes restants : Ajoutez les courgettes (et le chou-fleur ou le brocoli si vous les utilisez). Si vous utilisez des épinards surgelés, ajoutez-les également maintenant. Laissez mijoter encore 10-15 minutes, jusqu\'à ce que tous les légumes soient tendres mais pas trop cuits.\r\n * Ajoutez les pois chiches et les raisins secs : Incorporez les pois chiches rincés et égouttés ainsi que les raisins secs. Laissez mijoter pendant les 5 dernières minutes pour les réchauffer.\r\n * Préparez le couscous : Pendant que le ragoût mijote, préparez le couscous selon les instructions du paquet. Généralement, on verse le couscous dans un saladier, on ajoute un volume d\'eau bouillante salée équivalent au volume du couscous, on couvre et on laisse gonfler pendant 5-10 minutes. Égrainer ensuite le couscous à la fourchette avec un filet d\'huile d\'olive pour éviter qu\'il ne colle.\r\n * Servez : Disposez le couscous dans un grand plat de service. Nappez généreusement de ragoût de légumes. Parsemez d\'amandes effilées grillées (si vous en utilisez) et de coriandre fraîche ciselée.', 'cousveg.jpeg', ''),
(14, 'vegetarienne', 'yassa vegetarien', '* 500g de tofu ferme, pressé pour enlever l\'excès d\'eau et coupé en cubes de 2-3 cm\r\n * 3 gros oignons, émincés finement\r\n * Le jus de 3-4 citrons jaunes (environ 100-120ml)\r\n * 2 cuillères à soupe de moutarde (de Dijon de préférence)\r\n * 1-2 piments oiseaux (ou autre piment selon votre goût), épépinés et hachés finement (facultatif)\r\n * 2 gousses d\'ail, écrasées\r\n * 1 poivron (jaune ou rouge), coupé en lanières\r\n * 1 carotte, coupée en rondelles\r\n * 1 courgette, coupée en demi-rondelles\r\n * 2 cuillères à soupe d\'huile d\'olive\r\n * 1 feuille de laurier\r\n * Thym frais (quelques brins) ou séché (1/2 cuillère à café)\r\n * Sel et poivre au goût\r\n * Riz blanc, pour servir\r\n * Coriandre fraîche, ciselée (pour la garniture)\r\n(Facultatif) Autres légumes possibles :\r\n * Aubergine coupée en cubes\r\n * Champignons émincés\r\n * Olives vertes ou noires', '* Marinez le tofu : Dans un grand bol, mélangez le tofu en cubes avec la moitié du jus de citron, la moitié de la moutarde, la moitié de l\'ail haché, la moitié du piment haché (si utilisé), un peu de sel et de poivre. Laissez mariner au réfrigérateur pendant au moins 30 minutes, idéalement 1 à 2 heures pour que le tofu s\'imprègne des saveurs.\r\n * Faites revenir les oignons : Dans une grande poêle ou une cocotte, faites chauffer l\'huile d\'olive à feu moyen. Ajoutez les oignons émincés et faites-les cuire lentement pendant environ 15-20 minutes, en remuant de temps en temps, jusqu\'à ce qu\'ils soient bien fondants et légèrement caramélisés. C\'est une étape clé pour la saveur du yassa.\r\n * Ajoutez les légumes : Incorporez le poivron en lanières et les carottes en rondelles aux oignons. Faites cuire pendant 5 minutes en remuant. Ajoutez ensuite la courgette et les autres légumes facultatifs si vous les utilisez, et faites cuire encore 5 minutes.\r\n * Ajoutez la marinade et les aromates : Versez le tofu mariné (avec sa marinade) dans la cocotte avec les légumes. Ajoutez le reste du jus de citron, le reste de la moutarde, le reste de l\'ail, le reste du piment (si utilisé), la feuille de laurier et le thym. Salez et poivrez au goût.\r\n * Laissez mijoter : Portez à ébullition, puis réduisez le feu au minimum, couvrez et laissez mijoter pendant 20-25 minutes, en remuant de temps en temps, pour que les saveurs se mélangent bien et que les légumes soient tendres.\r\n * Vérifiez l\'assaisonnement : Goûtez et ajustez l\'assaisonnement en sel, poivre et jus de citron si nécessaire. Le yassa doit avoir une agréable acidité.\r\n * Servez : Retirez la feuille de laurier. Servez le yassa végétarien chaud sur un lit de riz blanc. Parsemez de coriandre fraîche ciselée avant de servir.', 'yassaveg.jpeg', '');

